internal static class CrosshairTests {
 static void VerifyPreviewBounds(string folder,Action<bool,string> check){
  string cache=Path.Combine(folder,"preview-fixture");Directory.CreateDirectory(cache);var visual=new System.Windows.Media.DrawingVisual();using(var dc=visual.RenderOpen())dc.DrawRectangle(System.Windows.Media.Brushes.Cyan,null,new System.Windows.Rect(0,0,32,32));var bitmap=new I.RenderTargetBitmap(32,32,96,96,System.Windows.Media.PixelFormats.Pbgra32);bitmap.Render(visual);var encoder=new I.PngBitmapEncoder();encoder.Frames.Add(I.BitmapFrame.Create(bitmap));using var memory=new MemoryStream();encoder.Save(memory);
  string json=JsonSerializer.Serialize(new{name="Oversized image",model=new[]{new{type="image",image="data:image/png;base64,"+Convert.ToBase64String(memory.ToArray()),width=1200,height=600,rotation=37,opacity=1,position=new{x=200,y=-50},layer=new{size=1}}}});File.WriteAllText(Path.Combine(cache,"community-1.json"),json);var design=new CrosshairDesign{Shape="Community",CommunityId=1,ImageFile="community-1.json"};
  foreach(bool fit in new[]{false,true}){
   var canvas=new System.Windows.Controls.Canvas{Width=320,Height=200};var view=new CrosshairView{Design=design,ImageFolder=cache,FitPreview=fit,Width=160,Height=85};System.Windows.Controls.Canvas.SetLeft(view,40);System.Windows.Controls.Canvas.SetTop(view,40);canvas.Children.Add(view);canvas.Measure(new System.Windows.Size(320,200));canvas.Arrange(new System.Windows.Rect(0,0,320,200));canvas.UpdateLayout();var rendered=new I.RenderTargetBitmap(320,200,96,96,System.Windows.Media.PixelFormats.Pbgra32);rendered.Render(canvas);var pixels=new byte[320*200*4];rendered.CopyPixels(pixels,320*4,0);var ink=Enumerable.Range(0,320*200).Where(i=>pixels[i*4+3]>0).ToArray();check(ink.Length>0,"oversized image remains visible: fitted="+fit);check(ink.All(i=>i%320>=40&&i%320<200&&i/320>=40&&i/320<125),"oversized image cannot paint outside its preview: fitted="+fit);if(fit)check(ink.All(i=>i%320>=47&&i%320<193&&i/320>=47&&i/320<118),"rotated and offset image fits inside thumbnail padding");else check(pixels[(40*320+40)*4+3]>0,"actual-size rendering remains independent of thumbnail fitting");var export=new I.PngBitmapEncoder();export.Frames.Add(I.BitmapFrame.Create(rendered));using(var stream=File.Create(Path.Combine(folder,fit?"preview-fitted.png":"preview-clipped.png")))export.Save(stream);
  }
 }
 static void VerifySize(string folder,Action<bool,string> check){
  var geometric=new CrosshairDesign{Shape="Cross",Length=12,Gap=4,Thickness=2,Outline=0};
  byte[] AppearanceMask(CrosshairDesign design,bool fit,bool lowResolution){var view=new CrosshairView{Design=design,FitPreview=fit,PhysicalPixels=lowResolution,ScalePercent=37,WidthPercent=246,HeightPercent=92,ResolutionScaleX=lowResolution?.5:1,ResolutionScaleY=lowResolution?.65:1,Width=63,Height=61};view.Measure(new System.Windows.Size(63,61));view.Arrange(new System.Windows.Rect(0,0,63,61));view.UpdateLayout();var target=new I.RenderTargetBitmap(63,61,96,96,System.Windows.Media.PixelFormats.Pbgra32);target.Render(view);var pixels=new byte[63*61*4];target.CopyPixels(pixels,63*4,0);return pixels.Where((_,i)=>i%4==3).ToArray();}
  foreach(string shape in new[]{"Cross","Ring","Chevron"})foreach(bool lowResolution in new[]{false,true})foreach(bool fit in new[]{false,true}){
   var design=new CrosshairDesign{Shape=shape,Thickness=1,Gap=8,Outline=1,Rotation=17};var baseline=AppearanceMask(design,fit,lowResolution);
   foreach(string finish in CrosshairAppearance.Finishes){design.Hue=137;design.Finish=finish;check(AppearanceMask(design,fit,lowResolution).SequenceEqual(baseline),"exact shape mask preserved: "+shape+" / "+finish+" / fitted="+fit+" / low-res="+lowResolution);}
  }
  var huePixels=new byte[]{0,0,255,255,0,0,0,0,0,0,0,255};CrosshairAppearance.Transform(huePixels,3,1,120,"Solid",100);
  check(huePixels[1]==255&&huePixels[2]==0,"hue shift converts red crosshair pixels to green");
  check(huePixels[7]==0&&huePixels[11]==255&&huePixels[8]==0,"appearance preserves transparent background and dark outlines");
  foreach(string finish in CrosshairAppearance.Finishes){var pixels=Enumerable.Range(0,64).SelectMany(_=>new byte[]{0,0,128,128}).ToArray();var alpha=pixels.Where((_,i)=>i%4==3).ToArray();CrosshairAppearance.Transform(pixels,8,8,60,finish,80);check(pixels.Where((_,i)=>i%4==3).SequenceEqual(alpha),"finish preserves crosshair alpha: "+finish);if(finish!="Solid")check(Enumerable.Range(0,64).Select(i=>(pixels[i*4],pixels[i*4+1],pixels[i*4+2])).Distinct().Count()>1,"finish creates color variation: "+finish);}
  var appearanceDesign=new CrosshairDesign{Hue=180,Finish="Stripes",TextureStrength=80};check(appearanceDesign.Copy().Hue==180&&appearanceDesign.Copy().Finish=="Stripes","appearance survives preset serialization");
  var appearanceView=new CrosshairView{Design=appearanceDesign};appearanceView.ExportPng(Path.Combine(folder,"appearance-stripes.png"));check(CrosshairView.LoadImage(Path.Combine(folder,"appearance-stripes.png")).PixelWidth==256,"styled crosshair exports to PNG");
  string lineFixture=Path.Combine(folder,"line-adjustment.json");File.WriteAllText(lineFixture,"{\"model\":[{\"type\":\"model\",\"line\":{\"length\":10,\"thickness\":2,\"offset\":4,\"color\":\"#00FFFF\",\"visible\":[\"left\",\"right\"]}}]}");
  var adjustable=new CrosshairCommunityDrawing(lineFixture);
  (int Ink,int Near,int Far) LinePixels(int thickness,int gap){var visual=new System.Windows.Media.DrawingVisual();using(var dc=visual.RenderOpen()){dc.PushTransform(new System.Windows.Media.TranslateTransform(32,32));adjustable.Draw(dc,thickness,gap);}var target=new I.RenderTargetBitmap(64,64,96,96,System.Windows.Media.PixelFormats.Pbgra32);target.Render(visual);var pixels=new byte[64*64*4];target.CopyPixels(pixels,64*4,0);return(Enumerable.Range(0,64*64).Count(i=>pixels[i*4+3]>0),pixels[(32*64+37)*4+3],pixels[(32*64+43)*4+3]);}
  check(LinePixels(6,4).Ink>LinePixels(1,4).Ink,"community thickness changes line coverage without scaling the whole design");
  var openGap=LinePixels(2,10);check(openGap.Near==0&&openGap.Far>0,"community gap moves lines outward and leaves the center clear");
  var adjustedDesign=new CrosshairDesign{CommunityThickness=1,CommunityGap=12};check(adjustedDesign.Copy().CommunityThickness==1&&adjustedDesign.Copy().CommunityGap==12,"line adjustments survive design serialization");
  // Compare the low-resolution overlay with an ordinary single-pass preview.
  byte[] LowResolutionPixels(bool overlay){var view=new CrosshairView{Design=new CrosshairDesign{Shape="Cross",Color="#00FFFF",Length=12,Gap=4,Thickness=1,Outline=0,Opacity=100,Dot=false},PhysicalPixels=overlay,ResolutionScaleX=.5,ResolutionScaleY=.5,Width=64,Height=64};view.Measure(new System.Windows.Size(64,64));view.Arrange(new System.Windows.Rect(0,0,64,64));view.UpdateLayout();var target=new I.RenderTargetBitmap(64,64,96,96,System.Windows.Media.PixelFormats.Pbgra32);target.Render(view);var pixels=new byte[64*64*4];target.CopyPixels(pixels,64*4,0);return pixels;}
  var normalPixels=LowResolutionPixels(false);var clarityPixels=LowResolutionPixels(true);
  check(Enumerable.Range(0,64*64).Sum(i=>(int)clarityPixels[i*4+3])>Enumerable.Range(0,64*64).Sum(i=>(int)normalPixels[i*4+3]),"low-resolution overlay gains visible pixel coverage");
  check(clarityPixels[(32*64+32)*4+3]==0&&clarityPixels.Take(64*4).All(value=>value==0),"clarity passes preserve center gap and transparent background");
  var solid=new System.Windows.Media.DrawingVisual();using(var dc=solid.RenderOpen())dc.DrawRectangle(System.Windows.Media.Brushes.Cyan,null,new System.Windows.Rect(0,0,32,32));var image=new I.RenderTargetBitmap(32,32,96,96,System.Windows.Media.PixelFormats.Pbgra32);image.Render(solid);image.Freeze();
  foreach(var importedDesign in new[]{new CrosshairDesign{Shape="Community",CommunityId=1,ImageFile="community-1.json",PreparedDrawing=adjustable,CommunityThickness=1,CommunityGap=10},new CrosshairDesign{Shape="Image",ImageFile="fixture.png",PreparedImage=image}}){var baseline=AppearanceMask(importedDesign,true,true);foreach(string finish in CrosshairAppearance.Finishes){importedDesign.Finish=finish;importedDesign.Hue=220;check(AppearanceMask(importedDesign,true,true).SequenceEqual(baseline),"imported shape mask preserved: "+importedDesign.Shape+" / "+finish);}}
  foreach(var design in new[]{geometric,new CrosshairDesign{Shape="Image",ImageFile="Classic.png",PreparedImage=image}}){
   var widths=new List<int>();foreach(int scale in new[]{50,100,200}){
    var view=new CrosshairView{Design=design,ImageFolder=folder,ScalePercent=scale,Width=256,Height=256};view.Measure(new System.Windows.Size(256,256));view.Arrange(new System.Windows.Rect(0,0,256,256));view.UpdateLayout();var bitmap=new I.RenderTargetBitmap(256,256,96,96,System.Windows.Media.PixelFormats.Pbgra32);bitmap.Render(view);var pixels=new byte[256*256*4];bitmap.CopyPixels(pixels,256*4,0);var columns=Enumerable.Range(0,256*256).Where(i=>pixels[i*4+3]>0).Select(i=>i%256).ToArray();widths.Add(columns.Max()-columns.Min()+1);
   }check(widths[0]<widths[1]&&widths[1]<widths[2],"size slider scales entire "+design.Shape+" crosshair");
   (int Width,int Height) Bounds(int x,int y){var view=new CrosshairView{Design=design,ImageFolder=folder,WidthPercent=x,HeightPercent=y,Width=256,Height=256};view.Measure(new System.Windows.Size(256,256));view.Arrange(new System.Windows.Rect(0,0,256,256));view.UpdateLayout();var bitmap=new I.RenderTargetBitmap(256,256,96,96,System.Windows.Media.PixelFormats.Pbgra32);bitmap.Render(view);var pixels=new byte[256*256*4];bitmap.CopyPixels(pixels,256*4,0);var ink=Enumerable.Range(0,256*256).Where(i=>pixels[i*4+3]>0).ToArray();return(ink.Max(i=>i%256)-ink.Min(i=>i%256)+1,ink.Max(i=>i/256)-ink.Min(i=>i/256)+1);}
   var baseline=Bounds(100,100);var wide=Bounds(200,100);var tall=Bounds(100,200);check(wide.Width>baseline.Width&&wide.Height==baseline.Height&&tall.Height>baseline.Height&&tall.Width==baseline.Width,"independent width and height controls: "+design.Shape);
  }
 }
 internal static int RunCommunity(string folder){Directory.CreateDirectory(folder);var log=new List<string>();int errors=0;foreach(string game in CrosshairCommunity.Games){var entries=CrosshairCommunity.Catalog.Where(x=>x.Games.Contains(game)&&x.FileId>0&&x.Bytes<20*1024*1024).OrderByDescending(x=>x.Rating).ThenBy(x=>x.Id).Take(4);foreach(var entry in entries){try{var design=entry.Preset.Design;CrosshairCommunity.Ensure(design,folder).GetAwaiter().GetResult();_ = new CrosshairCommunityDrawing(Path.Combine(folder,design.ImageFile));var view=new CrosshairView{Design=design,ImageFolder=folder};view.ExportPng(Path.Combine(folder,entry.Id+".png"));var bitmap=CrosshairView.LoadImage(Path.Combine(folder,entry.Id+".png"));var converted=new I.FormatConvertedBitmap(bitmap,System.Windows.Media.PixelFormats.Bgra32,null,0);var pixels=new byte[256*256*4];converted.CopyPixels(pixels,256*4,0);if(!Enumerable.Range(0,256*256).Any(i=>pixels[i*4+3]>0))throw new Exception("Resting layers are invisible.");var store=new CrosshairStore(folder);store.Settings.Presets=new(){entry.Preset};store.Settings.Randomizer=new(){Category="Saved presets",Duration=0};using(var randomizer=new CrosshairRandomizer(store,d=>store.Settings.Design=d,()=>{})){randomizer.Spin().GetAwaiter().GetResult();if(store.Settings.Design.CommunityId!=entry.Id)throw new Exception("Community randomizer did not apply its source design.");}log.Add("PASS download/render/randomizer "+game+" · "+entry.Id+" · "+entry.Name+" · "+entry.Url);}catch(Exception error){errors++;log.Add("FAIL "+game+" · "+entry.Id+" · "+entry.Name+" · "+error.GetBaseException().Message);}}}File.WriteAllLines(Path.Combine(folder,"community-live-tests.txt"),log);return errors==0?0:1;}
 internal static int Run(string folder){Directory.CreateDirectory(folder);var log=new List<string>();void Check(bool result,string caption){if(!result)throw new Exception(caption);log.Add("PASS "+caption);}void Reject(Action action,string caption){try{action();}catch(ArgumentException){log.Add("PASS "+caption);return;}throw new Exception(caption);}
  try{
   VerifyPreviewBounds(folder,Check);var compensation=CrosshairDisplay.Compensation(new(1280,1024),new(1920,1080));Check(Math.Abs(compensation.X*1920/1280-1)<0.000001&&Math.Abs(compensation.Y*1080/1024-1)<0.000001,"stretch compensation preserves native crosshair proportions");Check(CrosshairDisplay.Compensation(new(1920,1080),new(1920,1080))==(1d,1d),"native resolution uses unscaled crosshair pixels");Check(CrosshairDisplay.Compensation(new(1280,1024),default)==(1d,1d),"unavailable preferred mode safely retains physical pixels");
   Check(CrosshairStore.BuiltIn().Count()==32&&CrosshairStore.BuiltIn().Select(x=>x.Name).Distinct().Count()==32,"32 uniquely named crosshair designs");
   var catalog=CrosshairCommunity.Catalog;Check(catalog.Length==5980&&catalog.Select(x=>x.Id).Distinct().Count()==5980,"complete catalog snapshot has 5980 unique public uploads");
   var random=new Random(714);var options=new CrosshairRandomOptions{Category="Generated designs"};var current=new CrosshairDesign{Color="#123456",Shape="Diamond"};var generated=new HashSet<string>();for(int i=0;i<1000;i++){var design=CrosshairGenerator.Generate(random,options,current,Array.Empty<CrosshairPreset>());design.Validate();generated.Add(JsonSerializer.Serialize(design));}Check(generated.Count>990,"1000 valid random rolls produce diverse designs");
   foreach(var game in CrosshairCommunity.Games){var pool=CrosshairCommunity.Pool(game).ToArray();Check(pool.Length==catalog.Count(x=>x.Games.Contains(game)),"entire game catalog participates in randomizer: "+game);options.Category=game;for(int i=0;i<100;i++){var roll=CrosshairGenerator.Generate(random,options,current,Array.Empty<CrosshairPreset>());roll.Validate();if(!catalog.Single(x=>x.Id==roll.CommunityId).Games.Contains(game))throw new Exception("Wrong game rolled");}Check(true,"game randomizer preserves original community references: "+game);}
   Check(CrosshairCommunity.Pool("All community games").Count()==5980,"combined community randomizer includes every unique upload");options.Category="Generated designs";
   options.LockColor=options.LockShape=true;for(int i=0;i<100;i++){var design=CrosshairGenerator.Generate(random,options,current,Array.Empty<CrosshairPreset>());if(design.Color!=current.Color||design.Shape!=current.Shape)throw new Exception("Randomizer locks failed");}Check(true,"color and shape locks respected");options.LockShape=options.LockColor=false;
   foreach(string category in new[]{"Precision","Rings & targets","Creative"}){options.Category=category;for(int i=0;i<100;i++)CrosshairGenerator.Generate(random,options,current,Array.Empty<CrosshairPreset>()).Validate();Check(true,"valid generated category: "+category);}
   options.Category="Saved presets";Reject(()=>CrosshairGenerator.Generate(random,options,current,Array.Empty<CrosshairPreset>()),"empty saved-preset pool rejected");var original=new CrosshairDesign{Length=27};var recall=CrosshairGenerator.Generate(random,options,current,new[]{new CrosshairPreset{Design=original}});recall.Length=4;Check(original.Length==27,"saved-preset randomization does not mutate library");
   string state=Path.Combine(folder,"state-"+Guid.NewGuid().ToString("N"));var store=new CrosshairStore(state);store.Settings.Design=new(){Color="#55DDFF",Gap=9,Opacity=65};store.Settings.SizePercent=175;store.Settings.WidthPercent=150;store.Settings.HeightPercent=125;store.Settings.SpinKey="F9";store.Settings.SpinModifiers=0;store.Settings.OffsetX=-15;store.Settings.HideOnAim=true;store.SavePreset("Precision");store.Settings.Design.Gap=3;Check(store.Settings.Presets.Single().Design.Gap==9,"saved preset is independent of edits");store.Save();var loaded=new CrosshairStore(state);Check(loaded.Settings.Design.Gap==3&&loaded.Settings.Presets.Single().Design.Gap==9&&loaded.Settings.OffsetX==-15&&loaded.Settings.HideOnAim,"design, presets and position survive restart");Check(loaded.Settings.SizePercent==175&&loaded.Settings.WidthPercent==150&&loaded.Settings.HeightPercent==125,"overlay size survives restart");Check(loaded.Settings.SpinKey=="F9"&&loaded.Settings.SpinModifiers==0&&loaded.Settings.SpinShortcutEnabled,"configured global spin shortcut survives restart");Check(CrosshairHotkey.ValidKey("R")&&CrosshairHotkey.ValidKey("F24")&&CrosshairHotkey.ValidKey("OemOpenBrackets")&&CrosshairHotkey.ValidKey("NumPad5")&&!CrosshairHotkey.ValidKey("LeftCtrl")&&!CrosshairHotkey.ValidKey("garbage"),"global shortcut supports letters and function keys but rejects modifier-only bindings");Reject(()=>store.SavePreset("precision"),"duplicate preset names rejected");Reject(()=>store.SavePreset(""),"empty preset names rejected");
   foreach(var design in new[]{new CrosshairDesign{Shape="Unknown"},new CrosshairDesign{Color="red"},new CrosshairDesign{Opacity=0},new CrosshairDesign{Length=1000},new CrosshairDesign{Shape="Image"}})Reject(design.Validate,"invalid crosshair rejected");
   var center=CrosshairOverlay.Center(new(-1920,-240,1920,1080),12,-4);Check(center==new System.Drawing.Point(-948,296),"monitor centering supports negative desktop coordinates and offsets");
   foreach(var preset in CrosshairStore.BuiltIn()){preset.Design.Validate();var view=new CrosshairView{Design=preset.Design};string file=Path.Combine(folder,preset.Name.Replace(" ","-")+".png");view.ExportPng(file);var image=CrosshairView.LoadImage(file);Check(image.PixelWidth==256&&image.PixelHeight==256,"PNG export: "+preset.Name);var converted=new I.FormatConvertedBitmap(image,System.Windows.Media.PixelFormats.Bgra32,null,0);var pixels=new byte[256*256*4];converted.CopyPixels(pixels,256*4,0);Check(pixels[3]==0&&Enumerable.Range(0,256*256).Any(i=>pixels[i*4+3]>0),"transparent background and visible shape: "+preset.Name);}
   VerifySize(folder,Check);string imported=store.ImportImage(Path.Combine(folder,"Classic.png"));var custom=new CrosshairDesign{Shape="Image",ImageFile=imported};custom.Validate();var imageView=new CrosshairView{Design=custom,ImageFolder=state};imageView.ExportPng(Path.Combine(folder,"imported-image.png"));Check(File.Exists(Path.Combine(state,imported)),"imported PNG stored locally");
   foreach(string fixture in new[]{"community-model-fixture","community-image-fixture","community-ring-fixture"}){using var resource=typeof(CrosshairTests).Assembly.GetManifestResourceStream(fixture+".json")!;string source=Path.Combine(state,fixture+".json");using(var output=File.Create(source))resource.CopyTo(output);var drawing=new CrosshairCommunityDrawing(source);long fixtureId=fixture=="community-image-fixture"?6383250:fixture=="community-ring-fixture"?6166880:6443835;string cached=Path.Combine(state,"community-"+fixtureId+".json");File.Copy(source,cached,true);var communityDesign=new CrosshairDesign{Shape="Community",CommunityId=fixtureId,ImageFile="community-"+fixtureId+".json"};CrosshairCommunity.Ensure(communityDesign,state).GetAwaiter().GetResult();var view=new CrosshairView{Design=communityDesign,ImageFolder=state};string exported=Path.Combine(folder,fixture+".png");view.ExportPng(exported);var image=CrosshairView.LoadImage(exported);var converted=new I.FormatConvertedBitmap(image,System.Windows.Media.PixelFormats.Bgra32,null,0);var pixels=new byte[256*256*4];converted.CopyPixels(pixels,256*4,0);Check(pixels[3]==0&&Enumerable.Range(0,256*256).Any(i=>pixels[i*4+3]>0),"real Crosshair X layer fixture renders transparently: "+fixture);if(fixture=="community-ring-fixture")Check(pixels[(128*256+128)*4+3]==0,"creator ring outline preserves a transparent center");if(fixture=="community-model-fixture"){int pixelCenter=(128*256+128)*4;Check(pixels[pixelCenter+1]>200&&pixels[pixelCenter+2]>200,"creator's yellow center dot preserved");}}
   var communitySaved=new CrosshairDesign{Shape="Community",CommunityId=6443835,ImageFile="community-6443835.json"};store.Settings.Design=communitySaved;store.SavePreset("Community favorite");Check(new CrosshairStore(state).Settings.Presets.Last().Design.CommunityId==6443835,"community favorite survives restart with source reference");Reject(()=>new CrosshairDesign{Shape="Community",CommunityId=5,ImageFile="../file.json"}.Validate(),"community file traversal rejected");
   string json=Path.Combine(folder,"fixture-preset.json");File.WriteAllText(json,JsonSerializer.Serialize(new CrosshairDesign{Shape="Chevron",Color="#FF5555"}));Check(store.ImportDesign(json).Shape=="Chevron","JSON preset import");File.WriteAllText(json,JsonSerializer.Serialize(custom));Reject(()=>store.ImportDesign(json),"JSON image references rejected");File.WriteAllText(store.Path,"broken json");Check(!string.IsNullOrEmpty(new CrosshairStore(state).LoadError),"corrupt settings fall back with visible error");
   File.WriteAllLines(Path.Combine(folder,"crosshair-tests.txt"),log);return 0;
  }catch(Exception error){File.WriteAllLines(Path.Combine(folder,"crosshair-tests.txt"),log.Append(error.ToString()));return 1;}
 }
